<?php if($result): ?><section class="or-learn-panel"><h2><?= $h($result['title']??'نتیجه') ?></h2><?php if(isset($result['error'])): ?><p class="or-learn-error"><?= $h($result['error']) ?></p><?php else: ?><dl><?php foreach($result['metrics']??[] as [$label,$value]): ?><div><dt><?= $h($label) ?></dt><dd><?= $h($value) ?></dd></div><?php endforeach; ?></dl><?php if(!empty($result['note'])): ?><p class="or-learn-note-text"><?= $h($result['note']) ?></p><?php endif; ?><?php endif; ?></section><?php endif; ?><aside class="or-learn-note"><i class="fas fa-circle-info"></i><p>نتیجه محاسبه‌گر آموزشی در پروژه ذخیره نمی‌شود. برای تحلیل مسئله واقعی، پروژه بسازید و داده‌ها، قیود و فرض‌های مدل را بازبینی کنید.</p></aside></main>
<script>(()=>{const s=document.getElementById('or-tool'),fs=document.querySelectorAll('.or-learn-fields');function update(){fs.forEach(f=>{const on=f.dataset.tool===s.value;f.hidden=!on;f.querySelectorAll('input,textarea,select').forEach(x=>x.disabled=!on);});}s.addEventListener('change',update);update();})();</script>
